const readings = [22, 22, 8, 36, 32, 10, 30];
const filtered = readings.filter(value => value < 26);
const largest = Math.max(...filtered);
const connections = { 8: [10], 10: [30], 30: [32], 32: [36] };

function hasPath(start, connections) {
  const visited = new Set();
  const queue = [start];

  while (queue.length > 0) {
    const current = queue.shift();
    if (current === largest) return true;
    visited.add(current);

    const neighbors = connections[current] || [];
    for (const neighbor of neighbors) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }

  return false;
}

const result = hasPath(8, connections);
return result ? "Yes" : "No";
```

