const keptItems = items.filter(item => item < 9);
const largestItem = Math.max(...keptItems);
const connections = { 5: [11, 19], 11: [], 19: [25], 25: [] };

// Check if there's a path from 11 to largestItem
function hasPath(start, end, graph) {
  const visited = new Set();
  const queue = [start];

  while (queue.length > 0) {
    const current = queue.shift();
    if (current === end) return true;
    if (visited.has(current)) continue;
    visited.add(current);
    for (const neighbor of graph[current]) {
      if (!visited.has(neighbor)) {
        queue.push(neighbor);
      }
    }
  }
  return false;
}

const pathExists = hasPath(11, largestItem, connections);
return pathExists ? "Yes" : "No";
